"use client";

import * as React from "react";
import { Toggle as BaseToggle } from "@base-ui/react/toggle";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/registry/cmplt/lib/utils";

const toggleVariants = cva(
  "inline-flex items-center justify-center gap-1.5 font-medium transition-all duration-200 ease-cmplt-out cursor-pointer select-none focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-canvas disabled:pointer-events-none disabled:opacity-45 active:scale-[0.97]",
  {
    variants: {
      variant: {
        default:
          "bg-transparent text-fg-secondary hover:bg-subtle hover:text-fg-primary data-[pressed]:bg-subtle data-[pressed]:text-fg-primary data-[pressed]:shadow-cmplt-xs",
        outline:
          "border border-border-default bg-surface text-fg-secondary hover:bg-subtle hover:text-fg-primary data-[pressed]:border-accent data-[pressed]:bg-accent-subtle/30 data-[pressed]:text-fg-accent",
        accent:
          "border border-border-default bg-surface text-fg-secondary hover:bg-subtle hover:text-fg-primary data-[pressed]:border-accent data-[pressed]:bg-accent data-[pressed]:text-fg-on-accent",
      },
      size: {
        sm: "h-8 px-2.5 text-xs rounded-cmplt-sm min-w-8",
        md: "h-9 px-3 text-xs rounded-cmplt-md min-w-9",
        lg: "h-10 px-3.5 text-sm rounded-cmplt-md min-w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "md",
    },
  }
);

export interface ToggleProps
  extends React.ComponentPropsWithoutRef<typeof BaseToggle>,
    VariantProps<typeof toggleVariants> {}

const Toggle = React.forwardRef<HTMLButtonElement, ToggleProps>(
  ({ className, variant, size, ...props }, ref) => {
    return (
      <BaseToggle
        ref={ref}
        className={cn(toggleVariants({ variant, size }), className)}
        {...props}
      />
    );
  }
);
Toggle.displayName = "Toggle";

export { Toggle, toggleVariants };

"use client";

import * as React from "react";
import { ToggleGroup as BaseToggleGroup } from "@base-ui/react/toggle-group";
import { type VariantProps } from "class-variance-authority";
import { cn } from "@/registry/cmplt/lib/utils";
import { Toggle, toggleVariants } from "@/registry/cmplt/ui/toggle";

const ToggleGroupContext = React.createContext<
  VariantProps<typeof toggleVariants>
>({
  variant: "default",
  size: "md",
});

export interface ToggleGroupProps<Value extends string = string>
  extends React.ComponentPropsWithoutRef<typeof BaseToggleGroup<Value>>,
    VariantProps<typeof toggleVariants> {}

const ToggleGroup = React.forwardRef<
  HTMLDivElement,
  ToggleGroupProps<string>
>(({ className, variant = "default", size = "md", children, ...props }, ref) => {
  return (
    <BaseToggleGroup
      ref={ref}
      className={cn(
        "inline-flex items-center gap-1 rounded-cmplt-md p-1",
        variant === "default" && "bg-subtle/70 border border-border-subtle",
        variant === "outline" && "border border-border-default bg-surface",
        className
      )}
      {...props}
    >
      <ToggleGroupContext.Provider value={{ variant, size }}>
        {children}
      </ToggleGroupContext.Provider>
    </BaseToggleGroup>
  );
});
ToggleGroup.displayName = "ToggleGroup";

export interface ToggleGroupItemProps
  extends React.ComponentPropsWithoutRef<typeof Toggle> {}

const ToggleGroupItem = React.forwardRef<
  HTMLButtonElement,
  ToggleGroupItemProps
>(({ className, variant, size, ...props }, ref) => {
  const context = React.useContext(ToggleGroupContext);

  return (
    <Toggle
      ref={ref}
      variant={variant ?? context.variant ?? "default"}
      size={size ?? context.size ?? "md"}
      className={cn("data-[pressed]:shadow-cmplt-xs", className)}
      {...props}
    />
  );
});
ToggleGroupItem.displayName = "ToggleGroupItem";

export { ToggleGroup, ToggleGroupItem };
